import { useStore } from '~/app/store/store';
import {
  useWebAuthnCertificationOptionsMutation,
  useWebAuthnCertificationMutation,
} from '~/entities/biometric/api/use-webauthn-certification-mutation';
import {
  useWebAuthnRegisterOptionsMutation,
  useWebAuthnRegistrationMutation,
} from '~/entities/biometric/api/use-webauthn-registration-mutation';
import { useAuthnNativeCertification } from '~/entities/biometric/lib/use-authn-native-certification';
import { useAuthnNativeRegistration } from '~/entities/biometric/lib/use-authn-native-registration';
import { BiometricError } from '~/entities/biometric/model/types';
import { UserResponse } from '~/entities/pin/api/dtos/types';
import { useCreateUserMutation } from '~/entities/pin/api/use-create-user-mutation';
import { useRegPinNumMutation } from '~/entities/pin/api/use-reg-pin-num-mutation';
import { useVerifyPinMutation } from '~/entities/pin/api/use-verify-pin-mutation';
import { getUserRes, setUserRes } from '~/entities/user/api/use-get-cstmr-query';
import { CBDCAxiosError } from '~/shared/@types/error';
import { StepBeforeRegister } from '~/shared/api/dtos/enums';
import i18n from '~/shared/i18n/i18n';
import { useAlertDialog } from '~/shared/lib/hooks/use-alert-dialog';
import { useNavigate } from '~/shared/lib/hooks/use-navigate';
import { notiBar, snackBar } from '~/shared/lib/toast';
import { PATHS } from '~/shared/routes/paths';
import { closeDialog } from '~/shared/ui/dialogs';

export const useOnSubmit = () => {
  const { navigate } = useNavigate();
  const { openAlertDialog } = useAlertDialog();
  const { mutateAsync: createUser } = useCreateUserMutation({ throwOnError: false });
  const { mutateAsync: regPinNum } = useRegPinNumMutation({ throwOnError: false });
  const { mutateAsync: login } = useVerifyPinMutation({ throwOnError: false });
  const { mutateAsync: webAuthnRegisterOptions } = useWebAuthnRegisterOptionsMutation();
  const { mutateAsync: webAuthnRegister } = useWebAuthnRegistrationMutation();
  const { mutateAsync: webAuthnCertificationOptions } = useWebAuthnCertificationOptionsMutation();
  const { mutateAsync: webAuthnCertification } = useWebAuthnCertificationMutation();
  const { register: biometricRegister } = useAuthnNativeRegistration();
  const { certification: biometricCertification } = useAuthnNativeCertification();

  const callCreateUser = async () => {
    try {
      const userRes = getUserRes() as UserResponse;
      useStore.getState().authSlice.setJwt(null);
      const response = await createUser(userRes);
      //const response = null;

      setUserRes((prev) => ({
        ...prev,
        tbCstmrMastr: {
          ...prev.tbCstmrMastr,
          cstmrNo: response.cstmrNo,
        },
        transkeyModel: userRes.transkeyModel,
        sid: response.sid,
      }));

      //sid 재배치
      userRes.tbCstmrMastr = {
        ...userRes.tbCstmrMastr,
        cstmrNo: response.cstmrNo,
      };
      userRes.sid = response.sid;

      useStore.getState().authSlice.setJwt(null);
      await login(userRes);
      useStore.getState().superAppSlice.clearSuperAppData();
      notiBar(i18n.t('membershipComplete'));
      navigate(PATHS.home, { replace: true });
    } catch (e: unknown) {
      const data = (e as CBDCAxiosError)?.response?.data ?? {};
      if (data?.message) {
        snackBar(data?.message);
        openAlertDialog({ message: data.message });
      }
    }
  };

  const callRegPinNum = async () => {
    try {
      const userRes = getUserRes() as UserResponse;
      await regPinNum(userRes);
      snackBar(i18n.t('pwChangeComplete'));
      return true;
    } catch (e: unknown) {
      const data = (e as CBDCAxiosError)?.response?.data ?? {};
      if (data?.message) {
        snackBar(data?.message);
        openAlertDialog({ message: data.message });
      }
      return false;
    }
  };

  const callAuthnRegister = async () => {
    try {
      const userRes = getUserRes() as UserResponse;
      useStore.getState().authSlice.setJwt(null);

      // 1. 사용자 생성 및 cstmrNo 획득
      const response = await createUser(userRes);
      const cstmrNo = response.cstmrNo;

      if (!cstmrNo) {
        throw new Error('사용자 생성에 실패했습니다.');
      }

      // 2. userRes 업데이트
      setUserRes((prev) => ({
        ...prev,
        tbCstmrMastr: {
          ...prev.tbCstmrMastr,
          cstmrNo,
        },
        transkeyModel: userRes.transkeyModel,
        sid: response.sid,
      }));

      userRes.tbCstmrMastr = {
        ...userRes.tbCstmrMastr,
        cstmrNo,
      };
      userRes.sid = response.sid;

      // 3. 생체인증 등록
      // 3-1. WebAuthn options 요청
      const registerOptions = await webAuthnRegisterOptions({
        username: cstmrNo,
      });

      // 3-2. 네이티브에서 생체인증 등록
      // ⛔ 문제 발생 => 네이티브 환경이 아닙니다 문구 표출 후 화면 이동 없음, 사용자 정보 이미 등록됨
      // 변경 => 해당 error 문구 표출 후 login 수행하도록 변경
      const registrationCredential = await biometricRegister({
        webAuthnOptions: registerOptions.publicKey,
        username: cstmrNo,
        userRes: userRes,
        step: StepBeforeRegister.회원가입,
      });

      // 3-3. 서버에 등록 완료 요청
      await webAuthnRegister(registrationCredential.payload);

      // 4. 생체인증으로 로그인
      // 4-1. WebAuthn certification options 요청
      // const certificationOptions = await webAuthnCertificationOptions({
      //   username: cstmrNo,
      // });

      // if (isEmpty(certificationOptions.publicKey.allowCredentials)) {
      //   openAlertDialog({ message: '등록된 패스키가 없습니다. 핀번호로 로그인 해주세요.' });
      //   return;
      // }

      // 4-2. 네이티브에서 생체인증
      // const certificationCredential = await biometricCertification({
      //   webAuthnOptions: certificationOptions.publicKey,
      //   username: cstmrNo,
      // });

      // 4-3. 서버에 인증 요청
      //await webAuthnCertification(certificationCredential.payload);

      // 로그인
      await login(userRes);

      // 5. 완료 처리
      useStore.getState().superAppSlice.clearSuperAppData();
      notiBar(i18n.t('membershipComplete'));

      // // 6. 사업자 등록 묻기 (2025.11.26) => use-on-submit.ts : handleRegisterBusiness()
      // openAlertDialog({
      //   message: i18n.t('validation:registerBusinessInformation'),
      //   buttonLabel: [i18n.t('cancel'), i18n.t('confirm')],
      //   onConfirmClick: () => {
      //     //확인 클릭 시 사업자 등록 화면으로 이동
      //     navigate(PATHS.myWallet.business);
      //   },
      //   onCancelClick: () => {
      //     console.log('CLICK cancel button register business account');
      //     //취소 클릭 시 홈화면으로 이동
      //     navigate(PATHS.home, { replace: true });
      //   },
      // });
      //navigate(PATHS.home, { replace: true });
    } catch (e: any) {
      try {
        const parsed = JSON.parse(e.message);

        if (parsed.errorType === BiometricError.USER_CANCEL) {
          snackBar(parsed?.errorMessage || '패스키 등록을 취소하였습니다.');

          //로그인 setting
          const userRes = getUserRes() as UserResponse;

          useStore.getState().authSlice.setJwt(null);
          await login(userRes);
          useStore.getState().superAppSlice.clearSuperAppData();
          notiBar(i18n.t('membershipComplete'));

          //사업자 등록을 묻는 alert
          openAlertDialog({
            message: i18n.t('validation:registerBusinessInformation'),
            buttonLabel: [i18n.t('cancel'), i18n.t('confirm')],
            onConfirmClick: () => {
              //확인 클릭 시 사업자 등록 화면으로 이동
              closeDialog(() => {
                navigate(PATHS.myWallet.business, { state: { step: StepBeforeRegister.회원가입 } });
              });
            },
            onCancelClick: () => {
              closeDialog(async () => {
                //취소 클릭 시 홈화면으로 이동
                await login(userRes);
                useStore.getState().superAppSlice.clearSuperAppData();
                navigate(PATHS.home, { replace: true });
              });
            },
          });

          return;
        }

        //snackBar((e as Error)?.message || '생체인증 등록 중 오류가 발생했습니다.');
        openAlertDialog({ message: (e as Error)?.message || '생체인증 등록 중 오류가 발생했습니다.' });
      } catch {
        //console.log('일반 에러', e);
        return null;
      }
      throw e;
    }
  };

  return {
    callCreateUser,
    callRegPinNum,
    callAuthnRegister,
  };
};
