import { useMutation } from '@tanstack/react-query';
import axios from 'axios';
import { useStore } from '~/app/store/store';
import { PinNumRequestDTO } from '~/entities/pin/api/dtos/types';
import { CBDCAxiosError } from '~/shared/@types/error';
import { MutationOptions } from '~/shared/@types/query';
import { API_URLS } from '~/shared/api/api-urls';
import { resultify } from '~/shared/lib/utils/resultify';
import { CreateUserResponse } from './dtos/schemas';

const createUser = (pinModel: PinNumRequestDTO) => {
  return resultify(axios.post<CreateUserResponse>(`${API_URLS.getCommonV2Url('createUser')}`, pinModel));
};

export const useCreateUserMutation = (
  options?: MutationOptions<PinNumRequestDTO, CBDCAxiosError, CreateUserResponse>,
) => {
  const mutation = useMutation<CreateUserResponse, CBDCAxiosError, PinNumRequestDTO>({
    ...options,
    mutationFn: (pinModel: PinNumRequestDTO) => createUser(pinModel),
    onSuccess: () => {
      useStore.getState().pinSlice.setIncorrectPinCount(0);
    },
  });

  return {
    ...mutation,
  };
};
