import { PinInteractionMode } from '~/shared/api/dtos/enums';

// 생체인증 등록 네이티브 반환 타입 (attestation)
type WebAuthnRegistrationPayload = {
  id: string;
  type: string;
  rawId: string;
  response: {
    clientDataJSON: string;
    attestationObject: string;
  };
  errorMessage?: string;
};

// 생체인증 인증 네이티브 반환 타입 (assertion)
type WebAuthnAuthenticationPayload = {
  id: string;
  type: string;
  rawId: string;
  response: {
    clientDataJSON: string;
    authenticatorData: string;
    signature: string;
    userHandle: string | null;
  };
};

// 통합 타입 (등록과 인증 모두)
export type WebAuthnNativeResponse = WebAuthnRegistrationPayload | WebAuthnAuthenticationPayload;

export type WebAuthnFirstStepReq = {
  username: string;
  displayname?: string;
};

// 최종 요청 타입
export type WebAuthnFinishReq = {
  username: string;
  credential: WebAuthnNativeResponse;
  type: PinInteractionMode;
};

export type WebAuthnFinishRes = {
  success: boolean;
};

export type WebAuthnFirstStepRes = {
  username: string;
  publicKey: PublicKeyCredentialRequestOptions;
};

// 생체인증 네이티브 반환 타입
export type NativeAuthnResult = {
  success: boolean;
  payload: WebAuthnFinishReq;
  errorType: BiometricError | null;
  errorMessage: string | null;
};

// 생체인증 유형형
export enum BiometricType {
  TouchID = 'TouchID',
  FaceID = 'FaceID',
  Biometrics = 'Biometrics',
}

// 생체인증 에러 타입
export enum BiometricError {
  USER_CANCEL = 'USER_CANCEL',
  SYSTEM_CANCEL = 'SYSTEM_CANCEL',
  AUTHENTICATION_FAILED = 'AUTHENTICATION_FAILED',
  BIOMETRY_NOT_AVAILABLE = 'BIOMETRY_NOT_AVAILABLE',
  BIOMETRY_NOT_ENROLLED = 'BIOMETRY_NOT_ENROLLED',
  BIOMETRY_LOCKOUT = 'BIOMETRY_LOCKOUT',
  BIOMETRY_LOCKOUT_PERMANENT = 'BIOMETRY_LOCKOUT_PERMANENT',
  UNKNOWN_ERROR = 'UNKNOWN_ERROR',
}
